// POST: set the scenario and reset the counters and the log. GET: show them.
const st = $getWorkflowStaticData('global');
const inp = $input.first().json;
if (String(inp.method || '').toUpperCase() === 'POST' || (inp.body && Object.keys(inp.body).length)) {
  const b = inp.body || {};
  st.scenario = { chat: Array.isArray(b.chat) ? b.chat.map(String) : [], listen: Array.isArray(b.listen) ? b.listen.map(String) : [] };
  st.calls = { chat: 0, listen: 0 };
  st.log = [];
}
return [{ json: { statusCode: 200, body: { scenario: st.scenario || null, calls: st.calls || null, log: st.log || [] } } }];

// Shared by the chat and listen answers: the scenario is a list of answers per endpoint, one per call, set by
// POST /webhook/stub-control {chat: [...], listen: [...]}; after the list is used up every call gets 200.
// Entries: '200', '429', '429:ra=5' (Retry-After 5), '429:quota' (OpenAI insufficient_quota), '402' (Deepgram credit),
// '400:language' (Deepgram unknown language), '500', '503'. Every call is logged with its time for the pauses check.
const st = $getWorkflowStaticData('global');
st.scenario = st.scenario || { chat: [], listen: [] };
st.calls = st.calls || { chat: 0, listen: 0 };
st.log = st.log || [];
function answer(kind, req) {
  const n = st.calls[kind]++;
  const entry = String((st.scenario[kind] || [])[n] || '200');
  const [codeStr, ...flags] = entry.split(':');
  const code = Number(codeStr) || 200;
  const flag = flags.join(':');
  const m = flag.match(/^ra=(\d+)$/);
  const retry_after = m ? m[1] : '';
  st.log.push({ t: new Date().toISOString(), kind, call: n + 1, entry });
  return { code, flag, retry_after, n };
}

const req = $input.first().json.body || {};
const a = answer('chat', req);
let body;
if (a.code === 200 && a.flag === 'empty') {
  body = { id: 'stub', object: 'chat.completion', model: 'stub-model', choices: [{ index: 0, message: { role: 'assistant', content: JSON.stringify({ paragraphs: [] }) }, finish_reason: 'stop' }], usage: { prompt_tokens: 100, completion_tokens: 5 } };
} else if (a.code === 200) {
  // A clean-shaped answer built from the request: the TRANSCRIPT lines of the last user message, five lines a paragraph.
  // The transcript is in the first user message (the correction turn of attempt 2 carries only the error text);
  // paragraphs of at most 200 words so the answer passes the paragraph rules of clean.
  const msgs = Array.isArray(req.messages) ? req.messages : [];
  const user = msgs.find((x) => x.role === 'user' && String(x.content || '').includes('TRANSCRIPT'));
  const src = String((user && user.content) || '').split('\nTRANSCRIPT\n').pop();
  const lines = src.split('\n').map((l) => l.match(/^\[(\d+(?:\.\d+)?)\]\s*(.*)$/)).filter(Boolean);
  const paragraphs = [];
  for (const l of lines) { const ws = l[2].split(/\s+/).filter(Boolean); for (let i = 0; i < ws.length; i += 200) paragraphs.push({ start: Number(l[1]), text: ws.slice(i, i + 200).join(' ') }); }
  body = { id: 'stub', object: 'chat.completion', model: 'stub-model', choices: [{ index: 0, message: { role: 'assistant', content: JSON.stringify({ paragraphs }) }, finish_reason: 'stop' }], usage: { prompt_tokens: 100, completion_tokens: 50 } };
} else if (a.code === 429 && a.flag === 'quota') {
  body = { error: { message: 'You exceeded your current quota, please check your plan and billing details.', type: 'insufficient_quota', code: 'insufficient_quota' } };
} else if (a.code === 429) {
  body = { error: { message: 'Rate limit reached for requests', type: 'requests', code: 'rate_limit_exceeded' } };
} else {
  body = { error: { message: `stub answers ${a.code}`, type: 'server_error', code: null } };
}
return [{ json: { statusCode: a.code, body, retry_after: a.retry_after } }];

